import{_ as a,c as n,o as i,j as o,Y as s,t as r}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"git-check-ignore | x-cmd man (git man1) | Debug gitignore / exclude files","titleTemplate":false,"description":"x-cmd man (git man1 Manual Page) | git-check-ignore - Debug gitignore / exclude files","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"git-check-ignore | x-cmd man (git man1) | Debug gitignore / exclude files"}],["meta",{"name":"og:description","content":"x-cmd man (git man1 Manual Page) | git-check-ignore - Debug gitignore / exclude files"}]]},"headers":[],"params":{"isMan":true,"man":"git-check-ignore","category":"git man1","desc":"Debug gitignore / exclude files"},"relativePath":"git/man1/git-check-ignore.md","filePath":"git/man1/[man].md"}'),h={name:"git/man1/git-check-ignore.md"},l={class:"visually-hidden"};function p(t,e,g,c,d,u){return i(),n("div",null,[o("h1",l,r(t.$params.man),1),e[0]||(e[0]=s(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>git-check-ignore - Debug gitignore / exclude files</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-ignore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pathname</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">...</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> check-ignore</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [&lt;options&gt;] --stdin</span></span></code></pre></div><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>For each pathname given via the command-line or from a file via <strong>--stdin</strong>, check whether the file is excluded by .gitignore (or other input files to the exclude mechanism) and output the path if it is excluded.</p><p>By default, tracked files are not shown at all since they are not subject to exclude rules; but see &quot;--no-index&quot;.</p><h2 id="options" tabindex="-1">OPTIONS <a class="header-anchor" href="#options" aria-label="Permalink to &quot;OPTIONS&quot;">​</a></h2><p>-q, --quiet</p><blockquote><p>Don&#39;t output anything, just set exit status. This is only valid with a single pathname.</p></blockquote><p>-v, --verbose</p><blockquote><p>Instead of printing the paths that are excluded, for each path that matches an exclude pattern, print the exclude pattern together with the path. (Matching an exclude pattern usually means the path is excluded, but if the pattern begins with &quot;<strong>!</strong>&quot; then it is a negated pattern and matching it means the path is NOT excluded.)</p><p>For precedence rules within and between exclude sources, see <strong>gitignore</strong>(5).</p></blockquote><p>--stdin</p><blockquote><p>Read pathnames from the standard input, one per line, instead of from the command-line.</p></blockquote><p>-z</p><blockquote><p>The output format is modified to be machine-parsable (see below). If <strong>--stdin</strong> is also given, input paths are separated with a NUL character instead of a linefeed character.</p></blockquote><p>-n, --non-matching</p><blockquote><p>Show given paths which don&#39;t match any pattern. This only makes sense when <strong>--verbose</strong> is enabled, otherwise it would not be possible to distinguish between paths which match a pattern and those which don&#39;t.</p></blockquote><p>--no-index</p><blockquote><p>Don&#39;t look in the index when undertaking the checks. This can be used to debug why a path became tracked by e.g. <strong>git add .</strong> and was not ignored by the rules as expected by the user or when developing patterns including negation to match a path previously added with <strong>git add -f</strong>.</p></blockquote><h2 id="output" tabindex="-1">OUTPUT <a class="header-anchor" href="#output" aria-label="Permalink to &quot;OUTPUT&quot;">​</a></h2><p>By default, any of the given pathnames which match an ignore pattern will be output, one per line. If no pattern matches a given path, nothing will be output for that path; this means that path will not be ignored.</p><p>If <strong>--verbose</strong> is specified, the output is a series of lines of the form:</p><p>&lt;source&gt; &lt;COLON&gt; &lt;linenum&gt; &lt;COLON&gt; &lt;pattern&gt; &lt;HT&gt; &lt;pathname&gt;</p><p>&lt;pathname&gt; is the path of a file being queried, &lt;pattern&gt; is the matching pattern, &lt;source&gt; is the pattern&#39;s source file, and &lt;linenum&gt; is the line number of the pattern within that source. If the pattern contained a &quot;<strong>!</strong>&quot; prefix or &quot;<strong>/</strong>&quot; suffix, it will be preserved in the output. &lt;source&gt; will be an absolute path when referring to the file configured by <strong>core.excludesFile</strong>, or relative to the repository root when referring to <strong>.git/info/exclude</strong> or a per-directory exclude file.</p><p>If <strong>-z</strong> is specified, the pathnames in the output are delimited by the null character; if <strong>--verbose</strong> is also specified then null characters are also used instead of colons and hard tabs:</p><p>&lt;source&gt; &lt;NULL&gt; &lt;linenum&gt; &lt;NULL&gt; &lt;pattern&gt; &lt;NULL&gt; &lt;pathname&gt; &lt;NULL&gt;</p><p>If <strong>-n</strong> or <strong>--non-matching</strong> are specified, non-matching pathnames will also be output, in which case all fields in each output record except for &lt;pathname&gt; will be empty. This can be useful when running non-interactively, so that files can be incrementally streamed to STDIN of a long-running check-ignore process, and for each of these files, STDOUT will indicate whether that file matched a pattern or not. (Without this option, it would be impossible to tell whether the absence of output for a given file meant that it didn&#39;t match any pattern, or that the output hadn&#39;t been generated yet.)</p><p>Buffering happens as documented under the <strong>GIT_FLUSH</strong> option in <strong>git</strong>(1). The caller is responsible for avoiding deadlocks caused by overfilling an input buffer or reading from an empty output buffer.</p><h2 id="exit-status" tabindex="-1">EXIT STATUS <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;EXIT STATUS&quot;">​</a></h2><p>0</p><blockquote><p>One or more of the provided paths is ignored.</p></blockquote><p>1</p><blockquote><p>None of the provided paths are ignored.</p></blockquote><p>128</p><blockquote><p>A fatal error was encountered.</p></blockquote><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>gitignore</strong>(5) <strong>git-config</strong>(1) <strong>git-ls-files</strong>(1)</p><h2 id="git" tabindex="-1">GIT <a class="header-anchor" href="#git" aria-label="Permalink to &quot;GIT&quot;">​</a></h2><p>Part of the <strong>git</strong>(1) suite</p>`,40))])}const b=a(h,[["render",p]]);export{f as __pageData,b as default};
